#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> G(N, vector<int>(M));

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            cin >> G[i][j];
        }
    }

    int cnt0 = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int targetParity = (i + j) & 1;
            if ((G[i][j] & 1) != targetParity) {
                cnt0++;
            }
        }
    }

    int totalCells = N * M;
    int total = min(cnt0, totalCells - cnt0);
    int offset = (cnt0 <= totalCells - cnt0) ? 0 : 1;

    cout << total << '\n';

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int targetParity = (i + j + offset) & 1;
            int val = G[i][j];

            if ((val & 1) != targetParity) {
                val++;
            }

            cout << val << (j + 1 == M ? '\n' : ' ');
        }
    }

    return 0;
}
